"]=6755,["name"]="一小袋宝石",["nameEn"]="A Small Container of Gems",["quality"]=1,["level"]=0,["ilvl"]=25,["icon"]="Interface\\Icons\\inv_misc_ornatebox",["stats"]={},["effects"]={},["basis"]="site"}},["rep"]="棘齿城 +250",["repEn"]="Ratchet +250",["nameEn"]="Blueleaf Tubers",["instructionsEn"]="Grab a Crate with Holes. Grab a Snufflenose Command Stick. Grab and read the Snufflenose Owner's Manual. In Razorfen Kraul, use the Crate with Holes to summon a Snufflenose Gopher, and use the Command Stick on the gopher to make it search for Tubers. Bring 6 Blueleaf Tubers, the Snufflenose Command Stick and the Crate with Holes to Mebok Mizzyrix in Ratchet.",["fromEn"]="Mebok Mizzyrix · The Barrens · 62.4, 37.6",["prerequisitesEn"]="",["nameTw"]="藍葉薯",["sources"]={"https://foreverchanges.pro/dungeons/razorfen-kraul"},["sourceDate"]="2026-10-01",["conditionsSource"]="EverythingQuests Forever"},{["id"]=1144,["name"]="进口商威利克斯",["en"]="Willix the Importer",["instructions"]="护送进口商威利克斯逃出剃刀沼泽。",["from"]="进口商威利克斯 · 剃刀沼泽",["faction"]="both",["inside"]=false,["itemStart"]=false,["gatesKnown"]=false,["factionSource"]="archive-explicit",["prerequisites"]="",["steps"]={},["followups"]={},["rewards"]={{["id"]=6748,["name"]="猴子戒指",["nameEn"]="Monkey Ring",["quality"]=3,["slot"]="手指",["level"]=0,["ilvl"]=32,["icon"]="Interface\\Icons\\inv_jewelry_ring_14",["stats"]={{["label"]="敏捷",["value"]=7},{["label"]="精神",["value"]=7}},["effects"]={},["basis"]="site"},{["id"]=6750,["name"]="蛇环",["nameEn"]="Snake Hoop",["quality"]=3,["slot"]="手指",["level"]=0,["ilvl"]=32,["icon"]="Interface\\Icons\\inv_jewelry_ring_06",["stats"]={{["label"]="智力",["value"]=7},{["label"]="精神",["value"]=7}},["effects"]={},["basis"]="site"},{["id"]=6749,["name"]="Tiger Band",["nameEn"]="Tiger Band",["quality"]=2,["level"]=0,["ilvl"]=31,["slot"]=nil,["icon"]="Interface\\Icons\\inv_jewelry_ring_13",["stats"]={},["effects"]={},["effectsEn"]={},["referenceLines"]={"Binds when picked up","Finger","+6 Strength","Sell Price: 8s 97c"},["r