ck-spire"},["sourceDate"]="2026-10-01",["conditionsSource"]="Community minimum only; other conditions unverified"},{["id"]=4903,["name"]="高图斯的命令",["nameEn"]="Warlord's Command",["instructions"]="杀死欧莫克大王、指挥官沃恩和维姆萨拉克。找到重要的黑石文件，然后向卡加斯的军官高图斯汇报。",["instructionsEn"]="Slay Highlord Omokk, War Master Voone, and Overlord Wyrmthalak. Recover Important Blackrock Documents. Return to Warlord Goretooth in Kargath when the mission has been accomplished.",["from"]="Warlord Goretooth's Command",["fromEn"]="Warlord Goretooth's Command",["gatesKnown"]=true,["itemStart"]=true,["rewards"]={{["id"]=13958,["name"]="Wyrmthalak's Shackles",["nameEn"]="Wyrmthalak's Shackles",["quality"]=3,["level"]=0,["ilvl"]=60,["slot"]=nil,["icon"]="Interface\\Icons\\inv_bracer_04",["stats"]={},["effects"]={},["effectsEn"]={},["referenceLines"]={"Binds when picked up","Wrist\tCloth","37 Armor","+15 Spirit","+9 Intellect","Sell Price: 95s 5c"},["referenceLinesEn"]={"Binds when picked up","Wrist\tCloth","37 Armor","+15 Spirit","+9 Intellect","Sell Price: 95s 5c"},["basis"]="classic",["mapping"]="classic-reference",["uncertain"]=true,["bosses"]={},["sourceDate"]="2026-10-01",["rewardMode"]="choice"},{["id"]=13959,["name"]="Omokk's Girth Restrainer",["nameEn"]="Omokk's Girth Restrainer",["quality"]=3,["level"]=0,["ilvl"]=60,["slot"]=nil,["icon"]="Interface\\Icons\\inv_belt_13",["stats"]={},["effects"]={},["effectsEn"]={},["referenceLines"]={"Binds when picked up","Waist\tPlate","353 Armor","+15 Strength","+9 Stamina","Equip: Improves your chance to get a critical strike by 1%.","Sell Price: 95s 42c"},["referenceLinesEn"]={"Binds when picked up","Waist\tPlate","353 Armor","+15 Strength","+9 Stamina","Equip: Improves your chance to get a critical strike by 1%.","Sell Price: 95s 42c"},["basis"]="classic",["mapping"]="classic-reference",["uncertain"]=true,["bosses"]={},["sourceDate"]="2026-10-01",["rewardMode"]="choice"},{["id"]=13961,["name"]="Halycon's Muzzle",["nameEn"]="Halycon's Muzzle",["quality"]=3,["level